const css = code;
if (!/data-theme=["\']?dark["\']?\]\s*{/i.test(css)) throw new Error("Add a [data-theme=\"dark\"] scope.");
if (!/data-theme[^{]*{[^}]*--color-bg\s*:/i.test(css)) throw new Error("Re-declare --color-bg inside the dark scope.");
if (!/data-theme[^{]*{[^}]*--color-fg\s*:/i.test(css)) throw new Error("Re-declare --color-fg inside the dark scope.");

const css = code;
if (!/\.card\s*{[^}]*var\(\s*--color-bg/i.test(css)) throw new Error("The card's background should come from var(--color-bg).");
if (!/\.card\s*{[^}]*var\(\s*--color-fg/i.test(css)) throw new Error("The card's text color should come from var(--color-fg).");
if (!/\.card\s*{(?![^}]*#[0-9a-f]{3,8})/i.test(css)) throw new Error("No raw hex colors inside .card — tokens only.");
